lib='''from collections import Counter

def background(grid):
    """The most common cell color of the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def divider(grid, bg=None):
    """(orientation, index, color) of the full row or column of one color that is not the background; (None, None, None) if none."""
    bg = bg if bg is not None else background(grid)
    h, w = len(grid), len(grid[0])
    for i, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            return ('h', i, row[0])
    for j in range(w):
        if len({grid[i][j] for i in range(h)}) == 1 and grid[0][j] != bg:
            return ('v', j, grid[0][j])
    return (None, None, None)

def slide_to_divider(grid, line_color=8):
    """Translate the non-background, non-divider object until it touches the divider line, then draw a full parallel line of line_color just beyond it."""
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    o, d, dc = divider(grid, bg)
    out = [[bg] * w for _ in range(h)]
    cells = [(i, j) for i in range(h) for j in range(w) if grid[i][j] not in (bg, dc)]
    obj = grid[cells[0][0]][cells[0][1]]
    def paint(cs):
        for i, j in cs: out[i][j] = obj
    if o == 'h':
        for j in range(w): out[d][j] = dc
        mn = min(i for i, j in cells); mx = max(i for i, j in cells)
        if mn > d:
            s = mn - (d + 1); paint([(i - s, j) for i, j in cells])
            for j in range(w): out[mx - s + 1][j] = line_color
        else:
            s = d - 1 - mx; paint([(i + s, j) for i, j in cells])
            for j in range(w): out[mn + s - 1][j] = line_color
    else:
        for i in range(h): out[i][d] = dc
        mn = min(j for i, j in cells); mx = max(j for i, j in cells)
        if mn > d:
            s = mn - (d + 1); paint([(i, j - s) for i, j in cells])
            for i in range(h): out[i][mx - s + 1] = line_color
        else:
            s = d - 1 - mx; paint([(i, j + s) for i, j in cells])
            for i in range(h): out[i][mn + s - 1] = line_color
    return out
'''
